         fatalErrorCount = 1;
         problems = [{
             fatal: true,
             severity: 2,
             message: `Error checking file: ${error.message}`
         }];
     }
     return {
         filePath: filename,
         errorCount: problems.length,
         warningCount: 0,
         fatalErrorCount,
         messages: problems
     };
 }

